def P_constrained(X):
    Y = 3 - 2*X
    if X < 0 or Y < 0:
        return float('inf')

    term1 = X - Y

    sqrt_term_inside = 3*X - 2*X**2
    if sqrt_term_inside < 0:
        return float('inf')

    sqrt_XY = sqrt_term_inside**0.5

    term2 = (3*X - 2*X**2) - 2*X*sqrt_XY + X**2

    return 3 * term1 * term2

print(f"P(0.5) = {P_constrained(0.5)}")
print(f"P(1.25) = {P_constrained(1.25)}")
